; bios_fill.asm -- chapter 1: 768 bytes into the name table, three ways
; generated by gen01.py
        INCLUDE "msx.inc"
        OUTPUT "bios_fill.rom"
        ORG $4000
        CART_HEADER init

WRTVRM  EQU $004D               ; BIOS: write A to VRAM address HL
LDIRVM  EQU $005C               ; BIOS: copy BC bytes from (HL) to VRAM address DE
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $C0          ; Graphic I, display on
        VDP_REG 0, $00
        VDP_REG 2, $06          ; names at $1800
by_bios_byte:                   ; 1. one BIOS call per byte
        ld hl, $1800
        ld bc, 768
.next:  ld a, 1
        call WRTVRM
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .next
by_bios_block:                  ; 2. one BIOS call for the block
        ld hl, twos
        ld de, $1800
        ld bc, 768
        call LDIRVM
by_ports:                       ; 3. our own loop on the two ports
        di
        VRAM_WRITE $1800
        ld hl, threes
        ld c, VDP_DATA
        ld d, 3                 ; 3 x 256 bytes
.block: ld b, 0
.byte:  outi                    ; 18 T on the MSX ...
        jp nz, .byte            ; ... + 11: 29 T a byte
        dec d
        jr nz, .block
finished:
        jr finished
twos:   ds 768, 2
threes: ds 768, 3
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
